package com.rotinafamily.nativehosttest
import android.app.*; import android.content.*; import android.media.*; import android.provider.Settings
class AlarmService:Service(){companion object{const val START="rf.START";const val STOP="rf.STOP";const val CH="rf_alarm"};var p:MediaPlayer?=null
override fun onCreate(){super.onCreate();getSystemService(NotificationManager::class.java).createNotificationChannel(NotificationChannel(CH,"Alarmes Rotina Family",NotificationManager.IMPORTANCE_HIGH).apply{setSound(null,null)})}
override fun onStartCommand(i:Intent?,f:Int,id:Int):Int{if(i?.action==STOP){p?.release();p=null;stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();return START_NOT_STICKY};val title=i?.getStringExtra(AlarmScheduler.TITLE)?:"Tarefa";val open=PendingIntent.getActivity(this,2,Intent(this,AlarmActivity::class.java).putExtra(AlarmScheduler.TITLE,title),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);startForeground(3001,Notification.Builder(this,CH).setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("Rotina Family").setContentText(title).setCategory(Notification.CATEGORY_ALARM).setOngoing(true).setFullScreenIntent(open,true).build());val u=Settings.System.DEFAULT_ALARM_ALERT_URI?:Settings.System.DEFAULT_NOTIFICATION_URI;p=MediaPlayer().apply{setAudioAttributes(AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).build());setDataSource(this@AlarmService,u);isLooping=true;prepare();start()};return START_NOT_STICKY}
override fun onBind(i:Intent?)=null;override fun onDestroy(){p?.release();p=null;super.onDestroy()}}